package com.techconsulting.lending.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.Duration; import java.util.Date;
@Service public class JwtService { private final SecretKey key; private final Duration expiration; public JwtService(@Value("${app.jwt-secret}") String secret,@Value("${app.jwt-expiration:PT8H}") Duration expiration){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expiration=expiration;} public String create(Long id,String username){return Jwts.builder().subject(username).claim("uid",id).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiration.toMillis())).signWith(key).compact();} public Claims parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} }
